1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  AGENT_ADAPTER_TYPES,
5	  createEnvironmentSchema,
6	  getEnvironmentCapabilities,
7	  probeEnvironmentConfigSchema,
8	  updateEnvironmentSchema,
9	} from "@paperclipai/shared";
10	import { forbidden } from "../errors.js";
11	import { validate } from "../middleware/validate.js";
12	import {
13	  accessService,
14	  agentService,
15	  issueService,
16	  logActivity,
17	  projectService,
18	} from "../services/index.js";
19	import {
20	  normalizeEnvironmentConfigForPersistence,
21	  normalizeEnvironmentConfigForProbe,
22	  parseEnvironmentDriverConfig,
23	  readSshEnvironmentPrivateKeySecretId,
24	  type ParsedEnvironmentConfig,
25	} from "../services/environment-config.js";
26	import { probeEnvironment } from "../services/environment-probe.js";
27	import { secretService } from "../services/secrets.js";
28	import { listReadyPluginEnvironmentDrivers } from "../services/plugin-environment-driver.js";
29	import { assertCompanyAccess, getActorInfo } from "./authz.js";
30	import type { PluginWorkerManager } from "../services/plugin-worker-manager.js";
31	import { environmentService } from "../services/environments.js";
32	import { executionWorkspaceService } from "../services/execution-workspaces.js";
33	
34	export function environmentRoutes(
35	  db: Db,
36	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
37	) {
38	  const router = Router();
39	  const agents = agentService(db);
40	  const access = accessService(db);
41	  const svc = environmentService(db);
42	  const executionWorkspaces = executionWorkspaceService(db);
43	  const issues = issueService(db);
44	  const projects = projectService(db);
45	  const secrets = secretService(db);
46	
47	  function parseObject(value: unknown): Record<string, unknown> {
48	    return value && typeof value === "object" && !Array.isArray(value)
49	      ? (value as Record<string, unknown>)
50	      : {};
51	  }
52	
53	  function canCreateAgents(agent: { permissions: Record<string, unknown> | null | undefined }) {
54	    if (!agent.permissions || typeof agent.permissions !== "object") return false;
55	    return Boolean((agent.permissions as Record<string, unknown>).canCreateAgents);
56	  }
57	
58	  async function assertCanMutateEnvironments(req: Request, companyId: string) {
59	    assertCompanyAccess(req, companyId);
60	
61	    if (req.actor.type === "board") {
62	      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return;
63	      const allowed = await access.canUser(companyId, req.actor.userId, "environments:manage");
64	      if (!allowed) {
65	        throw forbidden("Missing permission: environments:manage");
66	      }
67	      return;
68	    }
69	
70	    if (!req.actor.agentId) {
71	      throw forbidden("Agent authentication required");
72	    }
73	
74	    const actorAgent = await agents.getById(req.actor.agentId);
75	    if (!actorAgent || actorAgent.companyId !== companyId) {
76	      throw forbidden("Agent key cannot access another company");
77	    }
78	
79	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "environments:manage");
80	    if (allowedByGrant || canCreateAgents(actorAgent)) {
81	      return;
82	    }
83	
84	    throw forbidden("Missing permission: environments:manage");
85	  }
86	
87	  async function actorCanReadEnvironmentConfigurations(req: Request, companyId: string) {
88	    assertCompanyAccess(req, companyId);
89	
90	    if (req.actor.type === "board") {
91	      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return true;
92	      return access.canUser(companyId, req.actor.userId, "environments:manage");
93	    }
94	
95	    if (!req.actor.agentId) return false;
96	    const actorAgent = await agents.getById(req.actor.agentId);
97	    if (!actorAgent || actorAgent.companyId !== companyId) return false;
98	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "environments:manage");
99	    return allowedByGrant || canCreateAgents(actorAgent);
100	  }
101	
102	  function redactEnvironmentForRestrictedView<T extends {
103	    config: Record<string, unknown>;
104	    metadata: Record<string, unknown> | null;
105	  }>(environment: T): T & { configRedacted: true; metadataRedacted: true } {
106	    return {
107	      ...environment,
108	      config: {},
109	      metadata: null,
110	      configRedacted: true,
111	      metadataRedacted: true,
112	    };
113	  }
114	
115	  function summarizeEnvironmentUpdate(
116	    patch: Record<string, unknown>,
117	    environment: {
118	      name: string;
119	      driver: string;
120	      status: string;
121	    },
122	  ): Record<string, unknown> {
123	    const details: Record<string, unknown> = {
124	      changedFields: Object.keys(patch).sort(),
125	    };
126	
127	    if (patch.name !== undefined) details.name = environment.name;
128	    if (patch.driver !== undefined) details.driver = environment.driver;
129	    if (patch.status !== undefined) details.status = environment.status;
130	    if (patch.description !== undefined) details.descriptionChanged = true;
131	    if (patch.config !== undefined) {
132	      details.configChanged = true;
133	      details.configTopLevelKeyCount =
134	        patch.config && typeof patch.config === "object" && !Array.isArray(patch.config)
135	          ? Object.keys(patch.config as Record<string, unknown>).length
136	          : 0;
137	    }
138	    if (patch.metadata !== undefined) {
139	      details.metadataChanged = true;
140	      details.metadataTopLevelKeyCount =
141	        patch.metadata && typeof patch.metadata === "object" && !Array.isArray(patch.metadata)
142	          ? Object.keys(patch.metadata as Record<string, unknown>).length
143	          : 0;
144	    }
145	
146	    return details;
147	  }
148	
149	  router.get("/companies/:companyId/environments", async (req, res) => {
150	    const companyId = req.params.companyId as string;
151	    assertCompanyAccess(req, companyId);
152	    const rows = await svc.list(companyId, {
153	      status: req.query.status as string | undefined,
154	      driver: req.query.driver as string | undefined,
155	    });
156	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(req, companyId);
157	    if (canReadConfigs) {
158	      res.json(rows);
159	      return;
160	    }
161	    res.json(rows.map((environment) => redactEnvironmentForRestrictedView(environment)));
162	  });
163	
164	  router.get("/companies/:companyId/environments/capabilities", async (req, res) => {
165	    const companyId = req.params.companyId as string;
166	    assertCompanyAccess(req, companyId);
167	    const pluginDrivers = await listReadyPluginEnvironmentDrivers({
168	      db,
169	      workerManager: options.pluginWorkerManager,
170	    });
171	    res.json(getEnvironmentCapabilities(
172	      AGENT_ADAPTER_TYPES,
173	      {
174	        sandboxProviders: Object.fromEntries(pluginDrivers.map((driver) => [
175	          driver.driverKey,
176	          {
177	            status: "supported" as const,
178	            supportsSavedProbe: true,
179	            supportsUnsavedProbe: true,
180	            supportsRunExecution: true,
181	            supportsReusableLeases: true,
182	            displayName: driver.displayName,
183	            description: driver.description,
184	            source: "plugin" as const,
185	            pluginKey: driver.pluginKey,
186	            pluginId: driver.pluginId,
187	            configSchema: driver.configSchema,
188	          },
189	        ])),
190	      },
191	    ));
192	  });
193	
194	  router.post("/companies/:companyId/environments", validate(createEnvironmentSchema), async (req, res) => {
195	    const companyId = req.params.companyId as string;
196	    await assertCanMutateEnvironments(req, companyId);
197	    const actor = getActorInfo(req);
198	    const input = {
199	      ...req.body,
200	      config: await normalizeEnvironmentConfigForPersistence({
201	        db,
202	        companyId,
203	        environmentName: req.body.name,
204	        driver: req.body.driver,
205	        config: req.body.config,
206	        actor: {
207	          agentId: actor.agentId,
208	          userId: actor.actorType === "user" ? actor.actorId : null,
209	        },
210	        pluginWorkerManager: options.pluginWorkerManager,
211	      }),
212	    };
213	    const environment = await svc.create(companyId, input);
214	    await logActivity(db, {
215	      companyId,
216	      actorType: actor.actorType,
217	      actorId: actor.actorId,
218	      agentId: actor.agentId,
219	      runId: actor.runId,
220	      action: "environment.created",
221	      entityType: "environment",
222	      entityId: environment.id,
223	      details: {
224	        name: environment.name,
225	        driver: environment.driver,
226	        status: environment.status,
227	      },
228	    });
229	    res.status(201).json(environment);
230	  });
231	
232	  router.get("/environments/:id", async (req, res) => {
233	    const environment = await svc.getById(req.params.id as string);
234	    if (!environment) {
235	      res.status(404).json({ error: "Environment not found" });
236	      return;
237	    }
238	    assertCompanyAccess(req, environment.companyId);
239	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(req, environment.companyId);
240	    if (canReadConfigs) {
241	      res.json(environment);
242	      return;
243	    }
244	    res.json(redactEnvironmentForRestrictedView(environment));
245	  });
246	
247	  router.get("/environments/:id/leases", async (req, res) => {
248	    const environment = await svc.getById(req.params.id as string);
249	    if (!environment) {
250	      res.status(404).json({ error: "Environment not found" });
251	      return;
252	    }
253	    assertCompanyAccess(req, environment.companyId);
254	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(req, environment.companyId);
255	    if (!canReadConfigs) {
256	      throw forbidden("Missing permission: environments:manage");
257	    }
258	    const leases = await svc.listLeases(environment.id, {
259	      status: req.query.status as string | undefined,
260	    });
261	    res.json(leases);
262	  });
263	
264	  router.get("/environment-leases/:leaseId", async (req, res) => {
265	    const lease = await svc.getLeaseById(req.params.leaseId as string);
266	    if (!lease) {
267	      res.status(404).json({ error: "Environment lease not found" });
268	      return;
269	    }
270	    assertCompanyAccess(req, lease.companyId);
271	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(req, lease.companyId);
272	    if (!canReadConfigs) {
273	      throw forbidden("Missing permission: environments:manage");
274	    }
275	    res.json(lease);
276	  });
277	
278	  router.patch("/environments/:id", validate(updateEnvironmentSchema), async (req, res) => {
279	    const existing = await svc.getById(req.params.id as string);
280	    if (!existing) {
281	      res.status(404).json({ error: "Environment not found" });
282	      return;
283	    }
284	    await assertCanMutateEnvironments(req, existing.companyId);
285	    const actor = getActorInfo(req);
286	    const nextDriver = req.body.driver ?? existing.driver;
287	    const nextName = req.body.name ?? existing.name;
288	    const configSource =
289	      req.body.config !== undefined
290	        ? req.body.driver !== undefined && req.body.driver !== existing.driver
291	          ? req.body.config
292	          : {
293	              ...parseObject(existing.config),
294	              ...parseObject(req.body.config),
295	            }
296	        : req.body.driver !== undefined && req.body.driver !== existing.driver
297	          ? {}
298	          : existing.config;
299	    const patch = {
300	      ...req.body,
301	      ...(req.body.config !== undefined || req.body.driver !== undefined
302	        ? {
303	            config: await normalizeEnvironmentConfigForPersistence({
304	              db,
305	              companyId: existing.companyId,
306	              environmentName: nextName,
307	              driver: nextDriver,
308	              config: configSource,
309	              actor: {
310	                agentId: actor.agentId,
311	                userId: actor.actorType === "user" ? actor.actorId : null,
312	              },
313	              pluginWorkerManager: options.pluginWorkerManager,
314	            }),
315	          }
316	        : {}),
317	    };
318	    const environment = await svc.update(existing.id, patch);
319	    if (!environment) {
320	      res.status(404).json({ error: "Environment not found" });
321	      return;
322	    }
323	    await logActivity(db, {
324	      companyId: environment.companyId,
325	      actorType: actor.actorType,
326	      actorId: actor.actorId,
327	      agentId: actor.agentId,
328	      runId: actor.runId,
329	      action: "environment.updated",
330	      entityType: "environment",
331	      entityId: environment.id,
332	      details: summarizeEnvironmentUpdate(patch as Record<string, unknown>, environment),
333	    });
334	    res.json(environment);
335	  });
336	
337	  router.delete("/environments/:id", async (req, res) => {
338	    const existing = await svc.getById(req.params.id as string);
339	    if (!existing) {
340	      res.status(404).json({ error: "Environment not found" });
341	      return;
342	    }
343	    await assertCanMutateEnvironments(req, existing.companyId);
344	    await Promise.all([
345	      executionWorkspaces.clearEnvironmentSelection(existing.companyId, existing.id),
346	      issues.clearExecutionWorkspaceEnvironmentSelection(existing.companyId, existing.id),
347	      projects.clearExecutionWorkspaceEnvironmentSelection(existing.companyId, existing.id),
348	    ]);
349	    const removed = await svc.remove(existing.id);
350	    if (!removed) {
351	      res.status(404).json({ error: "Environment not found" });
352	      return;
353	    }
354	    const secretId = readSshEnvironmentPrivateKeySecretId(existing);
355	    if (secretId) {
356	      await secrets.remove(secretId);
357	    }
358	    const actor = getActorInfo(req);
359	    await logActivity(db, {
360	      companyId: existing.companyId,
361	      actorType: actor.actorType,
362	      actorId: actor.actorId,
363	      agentId: actor.agentId,
364	      runId: actor.runId,
365	      action: "environment.deleted",
366	      entityType: "environment",
367	      entityId: removed.id,
368	      details: {
369	        name: removed.name,
370	        driver: removed.driver,
371	        status: removed.status,
372	      },
373	    });
374	    res.json(removed);
375	  });
376	
377	  router.post("/environments/:id/probe", async (req, res) => {
378	    const environment = await svc.getById(req.params.id as string);
379	    if (!environment) {
380	      res.status(404).json({ error: "Environment not found" });
381	      return;
382	    }
383	    await assertCanMutateEnvironments(req, environment.companyId);
384	    const actor = getActorInfo(req);
385	    const probe = await probeEnvironment(db, environment, {
386	      pluginWorkerManager: options.pluginWorkerManager,
387	    });
388	    await logActivity(db, {
389	      companyId: environment.companyId,
390	      actorType: actor.actorType,
391	      actorId: actor.actorId,
392	      agentId: actor.agentId,
393	      runId: actor.runId,
394	      action: "environment.probed",
395	      entityType: "environment",
396	      entityId: environment.id,
397	      details: {
398	        driver: environment.driver,
399	        ok: probe.ok,
400	        summary: probe.summary,
401	      },
402	    });
403	    res.json(probe);
404	  });
405	
406	  router.post(
407	    "/companies/:companyId/environments/probe-config",
408	    validate(probeEnvironmentConfigSchema),
409	    async (req, res) => {
410	      const companyId = req.params.companyId as string;
411	      await assertCanMutateEnvironments(req, companyId);
412	      const actor = getActorInfo(req);
413	      const normalizedConfig = await normalizeEnvironmentConfigForProbe({
414	        db,
415	        driver: req.body.driver,
416	        config: req.body.config,
417	        pluginWorkerManager: options.pluginWorkerManager,
418	      });
419	      const environment = {
420	        id: "unsaved",
421	        companyId,
422	        name: req.body.name?.trim() || "Unsaved environment",
423	        description: req.body.description ?? null,
424	        driver: req.body.driver,
425	        status: "active" as const,
426	        config: normalizedConfig,
427	        metadata: req.body.metadata ?? null,
428	        createdAt: new Date(),
429	        updatedAt: new Date(),
430	      };
431	      const probe = await probeEnvironment(db, environment, {
432	        pluginWorkerManager: options.pluginWorkerManager,
433	        resolvedConfig: {
434	          driver: req.body.driver,
435	          config: normalizedConfig,
436	        } as ParsedEnvironmentConfig,
437	      });
438	      await logActivity(db, {
439	        companyId,
440	        actorType: actor.actorType,
441	        actorId: actor.actorId,
442	        agentId: actor.agentId,
443	        runId: actor.runId,
444	        action: "environment.probed_unsaved",
445	        entityType: "environment",
446	        entityId: "unsaved",
447	        details: {
448	          driver: environment.driver,
449	          ok: probe.ok,
450	          summary: probe.summary,
451	          configTopLevelKeyCount: Object.keys(environment.config).length,
452	        },
453	      });
454	      res.json(probe);
455	    },
456	  );
457	
458	  return router;
459	}
